DROP TABLE IF EXISTS `attendances`;
CREATE TABLE `attendances` (
  `id` char(36) NOT NULL,
  `memberId` char(36) NOT NULL,
  `courseId` char(36) NOT NULL,
  `sessionDate` date NOT NULL,
  `status` enum('present','absent','late','excused') NOT NULL DEFAULT 'present',
  `markedBy` char(36) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `attendances_memberId_courseId_sessionDate_key` (`memberId`,`courseId`,`sessionDate`),
  KEY `attendances_memberId_idx` (`memberId`),
  KEY `attendances_courseId_idx` (`courseId`),
  KEY `attendances_sessionDate_idx` (`sessionDate`),
  CONSTRAINT `attendances_courseId_fkey` FOREIGN KEY (`courseId`) REFERENCES `courses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `attendances_memberId_fkey` FOREIGN KEY (`memberId`) REFERENCES `members` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

