INSERT INTO `audit_logs` (`id`, `userId`, `action`, `entity`, `entityId`, `oldValue`, `newValue`, `ip`, `createdAt`) VALUES ('2d4b3a6d-638e-4dce-a9b7-ff6548eaf607', 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', 'POST_V1', 'v1', 'ca39e064-73ef-4606-9519-9d9d18f8477e', NULL, '{"id":"ca39e064-73ef-4606-9519-9d9d18f8477e","title":"የአባልነት እድሳት ቅጽ (ዓመታዊ)","description":"በአዕማደ ሰላም ሰንበት ትምህርት ቤት የአገልግሎት አባላት ዓመታዊ ምዝገባ ማደሻና ቃል ኪዳን ማረጋገጫ ቅጽ","formSchema":{"titleAm":"የአባልነት እድሳት ቅጽ","titleEn":"Membership Renewal Form","descriptionAm":"የሰንበት ት/ቤት አባላት ዓመታዊ ምዝገባ ማደሻ","descriptionEn":"Annual Sunday School Membership Renewal","settings":{"allowOneResponsePerMember":true,"requireLogin":true,"confirmationMessageAm":"የአባልነት እድሳት ማመልከቻዎ በተሳካ ሁኔታ ደርሷል፤ በቅርቡ ይገመገማል።","confirmationMessageEn":"Your membership renewal application has been submitted successfully."},"fields":[{"name":"fullName","type":"text","labelAm":"ሙሉ ስም (ከነ አያት)","labelEn":"Full Name","required":true,"validation":{"minLength":3,"maxLength":100}},{"name":"baptismalName","type":"text","labelAm":"የክርስትና ስም","labelEn":"Baptismal Name","required":true,"validation":{"minLength":2}},{"name":"memberNo","type":"text","labelAm":"የአባልነት መለያ ቁጥር","labelEn":"Member ID Number","required":true,"validation":{"pattern":"^AS-\\\\d{4}-\\\\d{4}$"},"placeholderAm":"ምሳሌ፦ AS-2026-0001"},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone Number","required":true,"validation":{"minLength":9,"maxLength":20}},{"name":"email","type":"text","labelAm":"ኢሜይል አድራሻ","labelEn":"Email Address","required":false,"validation":{"pattern":"^[\\\\w-\\\\.]+@([\\\\w-]+\\\\.)+[\\\\w-]{2,4}$"}},{"name":"currentDepartment","type":"dropdown","labelAm":"ያሉበት የአገልግሎት ክፍል","labelEn":"Current Service Department","required":true,"options":[{"value":"ትምህርት","labelAm":"የትምህርት ክፍል","labelEn":"Education Department"},{"value":"መዝሙር","labelAm":"የመዝሙር ክፍል","labelEn":"Choir & Hymn Department"},{"value":"ልማት","labelAm":"የልማትና ገቢ ማሰባሰቢያ ክፍል","labelEn":"Development & Finance"},{"value":"ኪነጥበብ","labelAm":"የኪነ ጥበብና ድራማ ክፍል","labelEn":"Arts & Media"},{"value":"ሕፃናት","labelAm":"የሕፃናትና ታዳጊዎች ክፍል","labelEn":"Children & Youth"}]},{"name":"confessionFather","type":"text","labelAm":"የንስሐ አባት ስምና ቤተክርስቲያን","labelEn":"Confession Father & Parish","required":true,"validation":{"minLength":3}},{"name":"renewalYear","type":"number","labelAm":"የእድሳት ዓመተ ምሕረት (ዓ.ም)","labelEn":"Renewal Year (E.C)","required":true,"validation":{"min":2015,"max":2030}},{"name":"renewDate","type":"date","labelAm":"የማደሻ ቀን","labelEn":"Renewal Date","required":true},{"name":"serviceCommitment","type":"radio","labelAm":"የአገልግሎት ቁርጠኝነት ደረጃ","labelEn":"Service Commitment Level","required":true,"options":[{"value":"ሙሉ ጊዜ","labelAm":"ሙሉ ጊዜ (በየሳምንቱ ቅዳሜና እሑድ)","labelEn":"Full Time"},{"value":"በከፊል","labelAm":"በከፊል (በተመረጡ ቀናት)","labelEn":"Part Time"},{"value":"ልዩ ዝግጅት","labelAm":"በልዩ በዓላትና ዝግጅቶች ብቻ","labelEn":"Special Events Only"}]},{"name":"receiptFile","type":"file","labelAm":"የዓመታዊ መዋጮ ደረሰኝ ወይም ማረጋገጫ (ካለ)","labelEn":"Payment / Contribution Receipt (Optional)","required":false,"validation":{"allowedMimeTypes":["image/jpeg","image/png","image/webp","application/pdf"],"maxSizeBytes":5242880}},{"name":"agreement","type":"checkbox","labelAm":"የሰንበት ትምህርት ቤቱን መተዳደሪያ ደንብና መንፈሳዊ ሥነ-ምግባር አከብራለሁ","labelEn":"I commit to following the Sunday School constitution and ethics","required":true}]},"status":"open","openUntil":null,"allowOneResponsePerMember":true,"createdBy":"cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1","createdAt":"2026-10-17T18:09:58.765Z","updatedAt":"2026-10-17T18:09:58.765Z"}', '::1', '2026-10-17T18:09:58.822Z');
