DROP TABLE IF EXISTS `certificates`;
CREATE TABLE `certificates` (
  `id` char(36) NOT NULL,
  `memberId` char(36) NOT NULL,
  `courseId` char(36) NOT NULL,
  `code` varchar(100) NOT NULL,
  `issuedAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `certificates_code_key` (`code`),
  KEY `certificates_memberId_idx` (`memberId`),
  KEY `certificates_courseId_idx` (`courseId`),
  CONSTRAINT `certificates_courseId_fkey` FOREIGN KEY (`courseId`) REFERENCES `courses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `certificates_memberId_fkey` FOREIGN KEY (`memberId`) REFERENCES `members` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `contributions`;
CREATE TABLE `contributions` (
  `id` char(36) NOT NULL,
  `memberId` char(36) NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `type` varchar(50) NOT NULL,
  `paymentMethod` varchar(50) DEFAULT NULL,
  `period` varchar(50) DEFAULT NULL,
  `receiptNo` varchar(100) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `paidAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `recordedBy` char(36) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `contributions_receiptNo_key` (`receiptNo`),
  KEY `contributions_memberId_idx` (`memberId`),
  KEY `contributions_type_idx` (`type`),
  KEY `contributions_paidAt_idx` (`paidAt`),
  CONSTRAINT `contributions_memberId_fkey` FOREIGN KEY (`memberId`) REFERENCES `members` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

