DROP TABLE IF EXISTS `courses`;
CREATE TABLE `courses` (
  `id` char(36) NOT NULL,
  `titleAm` varchar(200) NOT NULL,
  `titleEn` varchar(200) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `level` varchar(50) DEFAULT NULL,
  `teacherId` char(36) DEFAULT NULL,
  `schedule` varchar(200) DEFAULT NULL,
  `capacity` int(11) DEFAULT NULL,
  `startDate` datetime(3) DEFAULT NULL,
  `endDate` datetime(3) DEFAULT NULL,
  `status` enum('draft','open','closed','archived') NOT NULL DEFAULT 'draft',
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `courses_status_idx` (`status`),
  KEY `courses_teacherId_idx` (`teacherId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `courses` (`id`, `titleAm`, `titleEn`, `description`, `level`, `teacherId`, `schedule`, `capacity`, `startDate`, `endDate`, `status`, `createdAt`, `updatedAt`) VALUES ('00ddec9c-c0fd-444e-bc2f-70266bb175b1', 'ነገረ ማርያም (Mariology)', 'Mariology: The Mystery of the Theotokos', 'የእመቤታችን ቅድስት ድንግል ማርያም ዘላለማዊ ድንግልና፣ አማላጅነትና ክብረ ቅድስና', 'ደረጃ ፪', 'eb1df808-a32f-46a1-b286-fc94d58e8426', 'ረቡዕ ማታ 12:00 - 1:30', 50, '2026-09-01T00:00:00.000Z', '2027-06-30T00:00:00.000Z', 'open', '2026-10-17T17:56:56.296Z', '2026-10-17T17:56:56.296Z');
INSERT INTO `courses` (`id`, `titleAm`, `titleEn`, `description`, `level`, `teacherId`, `schedule`, `capacity`, `startDate`, `endDate`, `status`, `createdAt`, `updatedAt`) VALUES ('1f65d275-bd92-4f3e-97ec-c30ee69742e4', 'ሥርዓተ ቤተ ክርስቲያንና ምሥጢራት', 'Church Liturgy and Holy Sacraments', 'ሰባቱ ምሥጢራተ ቤተ ክርስቲያን፣ የቅዳሴ ሥርዓትና የበዓላት አከባበር ትምህርት', 'ደረጃ ፪', 'eb1df808-a32f-46a1-b286-fc94d58e8426', 'እሑድ ከሰዓት 3:00 - 5:00', 35, '2026-09-01T00:00:00.000Z', '2027-06-30T00:00:00.000Z', 'open', '2026-10-17T17:56:56.269Z', '2026-10-17T17:56:56.269Z');
INSERT INTO `courses` (`id`, `titleAm`, `titleEn`, `description`, `level`, `teacherId`, `schedule`, `capacity`, `startDate`, `endDate`, `status`, `createdAt`, `updatedAt`) VALUES ('b77b01ae-d2f8-4169-8140-d728e641d14b', 'የመጽሐፍ ቅዱስ ጥናት ፩ (ኦሪትና ታሪክ)', 'Biblical Studies I (Pentateuch & History)', 'ከኦሪት ዘፍጥረት እስከ ነቢያት መጻሕፍት ያለው ጥልቅ መንፈሳዊ ትንታኔና የትርጓሜ ጥናት', 'ደረጃ ፩', 'eb1df808-a32f-46a1-b286-fc94d58e8426', 'ቅዳሜ ከሰዓት 8:00 - 10:00', 40, '2026-09-01T00:00:00.000Z', '2027-06-30T00:00:00.000Z', 'open', '2026-10-17T17:56:56.225Z', '2026-10-17T17:56:56.225Z');
INSERT INTO `courses` (`id`, `titleAm`, `titleEn`, `description`, `level`, `teacherId`, `schedule`, `capacity`, `startDate`, `endDate`, `status`, `createdAt`, `updatedAt`) VALUES ('bea49622-5f95-4013-bbcd-c70e7aa4ab4d', 'የግዕዝ ቋንቋ መሠረታዊ ጥናት', 'Introduction to Ge\'ez Language', 'የግዕዝ ፊደላት፣ ሰዋስው፣ ቃላት ግንባታና የጸሎት መጻሕፍት ንባብ', 'ደረጃ ፩', 'eb1df808-a32f-46a1-b286-fc94d58e8426', 'ቅዳሜ ጠዋት 3:00 - 5:00', 30, '2026-09-01T00:00:00.000Z', '2027-06-30T00:00:00.000Z', 'open', '2026-10-17T17:56:56.327Z', '2026-10-17T17:56:56.327Z');
INSERT INTO `courses` (`id`, `titleAm`, `titleEn`, `description`, `level`, `teacherId`, `schedule`, `capacity`, `startDate`, `endDate`, `status`, `createdAt`, `updatedAt`) VALUES ('f46cc5ec-6d9e-4d8e-aa79-3048cf7ae7be', 'ያሬዳዊ ዜማና የከበሮ አመታት', 'Saint Yared Hymnody & Liturgical Rhythms', 'የቅዱስ ያሬድ ዜማ ሥርዓት (ግዕዝ፣ ዕዝል፣ አራራይ) እና የዝማሬ መሣሪያዎች አጠቃቀም', 'ደረጃ ፫', 'eb1df808-a32f-46a1-b286-fc94d58e8426', 'እሑድ ጠዋት 2:00 - 4:00', 25, '2026-09-01T00:00:00.000Z', '2027-06-30T00:00:00.000Z', 'open', '2026-10-17T17:56:56.365Z', '2026-10-17T17:56:56.365Z');

DROP TABLE IF EXISTS `departments`;
CREATE TABLE `departments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nameAm` varchar(100) NOT NULL,
  `nameEn` varchar(100) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `departments_nameAm_key` (`nameAm`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (1, 'መዝሙር ክፍል', 'Choir & Hymnology Department', 'የያሬዳዊ ዜማና ቅዱሳት መዝሙራት ትምህርትና አገልግሎት ማስተባበሪያ ክፍል', '2026-10-17T17:56:55.544Z', '2026-10-17T17:56:55.544Z');
INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (2, 'ትምህርት ክፍል', 'Education Department', 'የነገረ መለኮት፣ የመጽሐፍ ቅዱስና የቤተ ክርስቲያን ሥርዓት ትምህርቶች ክፍል', '2026-10-17T17:56:55.562Z', '2026-10-17T17:56:55.562Z');
INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (3, 'ማኅበራዊ አገልግሎት ክፍል', 'Social Service Department', 'የበጎ አድራጎት፣ የልማትና የእርስ በእርስ መረዳዳት አገልግሎት ክፍል', '2026-10-17T17:56:55.572Z', '2026-10-17T17:56:55.572Z');
INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (4, 'ህፃናት ክፍል', 'Children Ministry Department', 'የህፃናት መንፈሳዊ አስተዳደግ፣ ትምህርትና መርሐ ግብራት ክፍል', '2026-10-17T17:56:55.591Z', '2026-10-17T17:56:55.591Z');
INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (5, 'ወጣቶች ክፍል', 'Youth Fellowship Department', 'የወጣቶች መንፈሳዊ ሕይወት ግንባታ፣ ውይይትና የሕብረት አገልግሎት ክፍል', '2026-10-17T17:56:55.603Z', '2026-10-17T17:56:55.603Z');

DROP TABLE IF EXISTS `device_tokens`;
CREATE TABLE `device_tokens` (
  `id` char(36) NOT NULL,
  `userId` char(36) NOT NULL,
  `token` varchar(500) NOT NULL,
  `platform` enum('android','ios','web') NOT NULL DEFAULT 'web',
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `device_tokens_token_key` (`token`),
  KEY `device_tokens_userId_idx` (`userId`),
  KEY `device_tokens_platform_idx` (`platform`),
  CONSTRAINT `device_tokens_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `enrollments`;
CREATE TABLE `enrollments` (
  `id` char(36) NOT NULL,
  `memberId` char(36) NOT NULL,
  `courseId` char(36) NOT NULL,
  `status` enum('active','completed','dropped') NOT NULL DEFAULT 'active',
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `enrollments_memberId_courseId_key` (`memberId`,`courseId`),
  KEY `enrollments_memberId_idx` (`memberId`),
  KEY `enrollments_courseId_idx` (`courseId`),
  KEY `enrollments_status_idx` (`status`),
  CONSTRAINT `enrollments_courseId_fkey` FOREIGN KEY (`courseId`) REFERENCES `courses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `enrollments_memberId_fkey` FOREIGN KEY (`memberId`) REFERENCES `members` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

