  KEY `favorites_mezmurId_idx` (`mezmurId`),
  CONSTRAINT `favorites_memberId_fkey` FOREIGN KEY (`memberId`) REFERENCES `members` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
