) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `forms`;
CREATE TABLE `forms` (
  `id` char(36) NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `formSchema` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`formSchema`)),
  `status` enum('draft','open','closed') NOT NULL DEFAULT 'draft',
  `openUntil` datetime(3) DEFAULT NULL,
  `allowOneResponsePerMember` tinyint(1) NOT NULL DEFAULT 0,
  `createdBy` char(36) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `forms_status_idx` (`status`),
  KEY `forms_openUntil_idx` (`openUntil`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `allowOneResponsePerMember`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('0814e911-cbd3-4fb1-967a-3c4e13fb4636', 'የበጎ ፈቃድ አገልግሎት ምዝገባ ቅጽ', 'በሰንበት ትምህርት ቤቱ በተለያዩ የበጎ አድራጎት፣ የልማትና የማኅበራዊ አገልግሎት ዘርፎች ለመሳተፍ የተዘጋጀ ቅጽ', '{"titleAm":"የበጎ ፈቃድ አገልግሎት ምዝገባ ቅጽ","titleEn":"Volunteer Ministry Sign-Up Form","fields":[{"name":"volunteerName","type":"text","labelAm":"የበጎ ፈቃደኛው ስም","labelEn":"Name","required":true},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone","required":true},{"name":"profession","type":"text","labelAm":"የትምህርት ደረጃ ወይም ሙያ","labelEn":"Profession","required":true},{"name":"interestedMinistries","type":"checkbox","labelAm":"ለማገልገል የሚፈልጓቸው ዘርፎች","labelEn":"Ministries","required":true,"options":[{"value":"media","labelAm":"ሚዲያና ቴክኖሎጂ"},{"value":"charity","labelAm":"መርጃ ማዕድ"}]},{"name":"experienceSummary","type":"textarea","labelAm":"ቀደም ሲል የነበሩዎት ልምዶች","labelEn":"Experience","required":true,"validation":{"minLength":10}},{"name":"hasConfessionFather","type":"radio","labelAm":"የንስሐ አባት አሎት?","labelEn":"Confession Father","required":true,"options":[{"value":"yes","labelAm":"አዎ አለኝ"},{"value":"no","labelAm":"የለኝም"}]}]}', 'open', '2026-12-31T23:59:59.000Z', 0, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:57.185Z', '2026-10-17T17:56:57.185Z');
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `allowOneResponsePerMember`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('68fd2e83-e99b-41b0-94fe-9ac47f4bdc8d', 'የሰንበት ትምህርት ቤት አገልግሎት እርካታ መጠይቅ ቅጽ', 'የአገልግሎታችንን ጥራት ለማሻሻል ከአባላትና ከምእመናን ግብረ-መልስ የሚሰበሰብበት የዳሰሳ ጥናት', '{"titleAm":"የሰንበት ትምህርት ቤት አገልግሎት እርካታ መጠይቅ ቅጽ","titleEn":"Sunday School Service Satisfaction Survey","fields":[{"name":"respondentRole","type":"dropdown","labelAm":"በሰንበት ት/ቤቱ ያለዎት ሚና","labelEn":"Role","required":true,"options":[{"value":"member","labelAm":"ተማሪ / አባል"},{"value":"parent","labelAm":"ወላጅ"}]},{"name":"overallSatisfaction","type":"radio","labelAm":"አጠቃላይ እርካታ","labelEn":"Satisfaction","required":true,"options":[{"value":"very_satisfied","labelAm":"በጣም ከፍተኛ"},{"value":"satisfied","labelAm":"ከፍተኛ"}]},{"name":"spiritualLessonsRating","type":"number","labelAm":"የትምህርት ጥራት (1-5)","labelEn":"Lessons Rating","required":true,"validation":{"min":1,"max":5}},{"name":"punctualityRating","type":"number","labelAm":"የሰዓት አከባበር (1-5)","labelEn":"Punctuality","required":true,"validation":{"min":1,"max":5}},{"name":"improvementSuggestions","type":"textarea","labelAm":"መሻሻል አለባቸው የሚሏቸው ጉዳዮች","labelEn":"Improvement Suggestions","required":true,"validation":{"minLength":5}}]}', 'open', '2026-12-31T23:59:59.000Z', 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:57.211Z', '2026-10-17T17:56:57.211Z');
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `allowOneResponsePerMember`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('897c4436-7593-4b20-835a-6d502f468d66', 'የልዩ ጉባኤና መርሐ ግብር ምዝገባ ቅጽ', 'በዓመታዊ ጉባኤያት፣ ሲምፖዚየሞችና መንፈሳዊ ጉዞዎች ላይ ለመሳተፍ የተዘጋጀ የምዝገባ ቅጽ', '{"titleAm":"የልዩ ጉባኤና መርሐ ግብር ምዝገባ ቅጽ","titleEn":"Special Event & Conference Registration Form","fields":[{"name":"participantName","type":"text","labelAm":"የተሳታፊ ሙሉ ስም","labelEn":"Full Name","required":true},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone Number","required":true},{"name":"ageGroup","type":"radio","labelAm":"የዕድሜ ክልል","labelEn":"Age Group","required":true,"options":[{"value":"21-30","labelAm":"ከ 21 - 30 ዓመት"},{"value":"31-50","labelAm":"ከ 31 - 50 ዓመት"}]},{"name":"parishChurch","type":"text","labelAm":"የመጡበት ደብር","labelEn":"Parish","required":true},{"name":"attendanceDays","type":"checkbox","labelAm":"የሚገኙባቸው ቀናት","labelEn":"Days","required":true,"options":[{"value":"ቅዳሜ","labelAm":"ቅዳሜ"},{"value":"እሑድ","labelAm":"እሑድ"}]},{"name":"transportation","type":"dropdown","labelAm":"የትራንስፖርት አገልግሎት","labelEn":"Transport","required":true,"options":[{"value":"ካዛንቺስ","labelAm":"ከካዛንቺስ"},{"value":"በራሴ","labelAm":"በራሴ"}]}]}', 'open', '2026-11-30T23:59:59.000Z', 0, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:57.169Z', '2026-10-17T17:56:57.169Z');
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `allowOneResponsePerMember`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('b5f64976-3c45-4b7d-a01f-ae51d4b583d1', 'የአባልነት እድሳት ቅጽ (ዓመታዊ)', 'በአዕማደ ሰላም ሰንበት ትምህርት ቤት የአገልግሎት አባላት ዓመታዊ ምዝገባ ማደሻና ቃል ኪዳን ማረጋገጫ ቅጽ', '{"titleAm":"የአባልነት እድሳት ቅጽ","titleEn":"Membership Renewal Form","fields":[{"name":"fullName","type":"text","labelAm":"ሙሉ ስም (ከነ አያት)","labelEn":"Full Name","required":true,"validation":{"minLength":3}},{"name":"baptismalName","type":"text","labelAm":"የክርስትና ስም","labelEn":"Baptismal Name","required":true},{"name":"memberNo","type":"text","labelAm":"የአባልነት መለያ ቁጥር","labelEn":"Member ID","required":true},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone Number","required":true},{"name":"currentDepartment","type":"dropdown","labelAm":"ያሉበት የአገልግሎት ክፍል","labelEn":"Department","required":true,"options":[{"value":"ትምህርት","labelAm":"የትምህርት ክፍል"},{"value":"መዝሙር","labelAm":"የመዝሙር ክፍል"},{"value":"ልማት","labelAm":"የልማት ክፍል"}]},{"name":"confessionFather","type":"text","labelAm":"የንስሐ አባት ስም","labelEn":"Confession Father","required":true},{"name":"renewalYear","type":"number","labelAm":"የእድሳት ዓ.ም","labelEn":"Renewal Year","required":true,"validation":{"min":2015,"max":2030}},{"name":"renewDate","type":"date","labelAm":"የማደሻ ቀን","labelEn":"Renewal Date","required":true},{"name":"serviceCommitment","type":"radio","labelAm":"የአገልግሎት ቁርጠኝነት","labelEn":"Service Commitment","required":true,"options":[{"value":"ሙሉ ጊዜ","labelAm":"ሙሉ ጊዜ"},{"value":"በከፊል","labelAm":"በከፊል"}]},{"name":"agreement","type":"checkbox","labelAm":"የሰንበት ት/ቤቱን መተዳደሪያ ደንብ አከብራለሁ","labelEn":"I agree to bylaws","required":true}]}', 'open', '2026-12-31T23:59:59.000Z', 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:57.149Z', '2026-10-17T17:56:57.149Z');
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `allowOneResponsePerMember`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('ca39e064-73ef-4606-9519-9d9d18f8477e', 'የአባልነት እድሳት ቅጽ (ዓመታዊ)', 'በአዕማደ ሰላም ሰንበት ትምህርት ቤት የአገልግሎት አባላት ዓመታዊ ምዝገባ ማደሻና ቃል ኪዳን ማረጋገጫ ቅጽ', '{"titleAm":"የአባልነት እድሳት ቅጽ","titleEn":"Membership Renewal Form","descriptionAm":"የሰንበት ት/ቤት አባላት ዓመታዊ ምዝገባ ማደሻ","descriptionEn":"Annual Sunday School Membership Renewal","settings":{"allowOneResponsePerMember":true,"requireLogin":true,"confirmationMessageAm":"የአባልነት እድሳት ማመልከቻዎ በተሳካ ሁኔታ ደርሷል፤ በቅርቡ ይገመገማል።","confirmationMessageEn":"Your membership renewal application has been submitted successfully."},"fields":[{"name":"fullName","type":"text","labelAm":"ሙሉ ስም (ከነ አያት)","labelEn":"Full Name","required":true,"validation":{"minLength":3,"maxLength":100}},{"name":"baptismalName","type":"text","labelAm":"የክርስትና ስም","labelEn":"Baptismal Name","required":true,"validation":{"minLength":2}},{"name":"memberNo","type":"text","labelAm":"የአባልነት መለያ ቁጥር","labelEn":"Member ID Number","required":true,"validation":{"pattern":"^AS-\\\\d{4}-\\\\d{4}$"},"placeholderAm":"ምሳሌ፦ AS-2026-0001"},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone Number","required":true,"validation":{"minLength":9,"maxLength":20}},{"name":"email","type":"text","labelAm":"ኢሜይል አድራሻ","labelEn":"Email Address","required":false,"validation":{"pattern":"^[\\\\w-\\\\.]+@([\\\\w-]+\\\\.)+[\\\\w-]{2,4}$"}},{"name":"currentDepartment","type":"dropdown","labelAm":"ያሉበት የአገልግሎት ክፍል","labelEn":"Current Service Department","required":true,"options":[{"value":"ትምህርት","labelAm":"የትምህርት ክፍል","labelEn":"Education Department"},{"value":"መዝሙር","labelAm":"የመዝሙር ክፍል","labelEn":"Choir & Hymn Department"},{"value":"ልማት","labelAm":"የልማትና ገቢ ማሰባሰቢያ ክፍል","labelEn":"Development & Finance"},{"value":"ኪነጥበብ","labelAm":"የኪነ ጥበብና ድራማ ክፍል","labelEn":"Arts & Media"},{"value":"ሕፃናት","labelAm":"የሕፃናትና ታዳጊዎች ክፍል","labelEn":"Children & Youth"}]},{"name":"confessionFather","type":"text","labelAm":"የንስሐ አባት ስምና ቤተክርስቲያን","labelEn":"Confession Father & Parish","required":true,"validation":{"minLength":3}},{"name":"renewalYear","type":"number","labelAm":"የእድሳት ዓመተ ምሕረት (ዓ.ም)","labelEn":"Renewal Year (E.C)","required":true,"validation":{"min":2015,"max":2030}},{"name":"renewDate","type":"date","labelAm":"የማደሻ ቀን","labelEn":"Renewal Date","required":true},{"name":"serviceCommitment","type":"radio","labelAm":"የአገልግሎት ቁርጠኝነት ደረጃ","labelEn":"Service Commitment Level","required":true,"options":[{"value":"ሙሉ ጊዜ","labelAm":"ሙሉ ጊዜ (በየሳምንቱ ቅዳሜና እሑድ)","labelEn":"Full Time"},{"value":"በከፊል","labelAm":"በከፊል (በተመረጡ ቀናት)","labelEn":"Part Time"},{"value":"ልዩ ዝግጅት","labelAm":"በልዩ በዓላትና ዝግጅቶች ብቻ","labelEn":"Special Events Only"}]},{"name":"receiptFile","type":"file","labelAm":"የዓመታዊ መዋጮ ደረሰኝ ወይም ማረጋገጫ (ካለ)","labelEn":"Payment / Contribution Receipt (Optional)","required":false,"validation":{"allowedMimeTypes":["image/jpeg","image/png","image/webp","application/pdf"],"maxSizeBytes":5242880}},{"name":"agreement","type":"checkbox","labelAm":"የሰንበት ትምህርት ቤቱን መተዳደሪያ ደንብና መንፈሳዊ ሥነ-ምግባር አከብራለሁ","labelEn":"I commit to following the Sunday School constitution and ethics","required":true}]}', 'open', NULL, 1, 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', '2026-10-17T18:09:58.765Z', '2026-10-17T18:09:58.765Z');
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `allowOneResponsePerMember`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('d7f04884-1fe3-44d1-b21a-7448dabf685b', 'የስእለትና የልማት ቃል ኪዳን መመዝገቢያ ቅጽ', 'ለቤተ ክርስቲያንና ሰንበት ትምህርት ቤት ሕንፃ፣ መጻሕፍት ሕትመትና ልማት የሚደረግ የገንዘብ ቃል ኪዳን መመዝገቢያ', '{"titleAm":"የስእለትና የልማት ቃል ኪዳን መመዝገቢያ ቅጽ","titleEn":"Pledge & Contribution Commitment Form","fields":[{"name":"pledgerName","type":"text","labelAm":"የሰጪው ሙሉ ስም","labelEn":"Pledger Name","required":true},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone Number","required":true},{"name":"pledgePurpose","type":"dropdown","labelAm":"የስእለት ዓላማ","labelEn":"Purpose","required":true,"options":[{"value":"building","labelAm":"ለሕንፃ ግንባታ"},{"value":"books","labelAm":"ለመጻሕፍት ሕትመት"}]},{"name":"pledgeFrequency","type":"radio","labelAm":"የክፍያ ሁኔታ","labelEn":"Frequency","required":true,"options":[{"value":"monthly","labelAm":"ወርሃዊ"},{"value":"one_time","labelAm":"የአንድ ጊዜ"}]},{"name":"pledgedAmount","type":"number","labelAm":"የተገባው መጠን (ብር)","labelEn":"Amount","required":true,"validation":{"min":100}},{"name":"pledgeStartDate","type":"date","labelAm":"የሚጀመርበት ቀን","labelEn":"Start Date","required":true}]}', 'open', '2026-12-31T23:59:59.000Z', 0, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:57.198Z', '2026-10-17T17:56:57.198Z');
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `allowOneResponsePerMember`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('e53baec3-d3a5-43a1-8406-a606343dcacc', 'የአባልነት እድሳት ቅጽ (ዓመታዊ)', 'በአዕማደ ሰላም ሰንበት ትምህርት ቤት የአገልግሎት አባላት ዓመታዊ ምዝገባ ማደሻና ቃል ኪዳን ማረጋገጫ ቅጽ', '{"titleAm":"የአባልነት እድሳት ቅጽ (ዓመታዊ)","titleEn":"የአባልነት እድሳት ቅጽ (ዓመታዊ)","descriptionAm":"በአዕማደ ሰላም ሰንበት ትምህርት ቤት የአገልግሎት አባላት ዓመታዊ ምዝገባ ማደሻና ቃል ኪዳን ማረጋገጫ ቅጽ","descriptionEn":"በአዕማደ ሰላም ሰንበት ትምህርት ቤት የአገልግሎት አባላት ዓመታዊ ምዝገባ ማደሻና ቃል ኪዳን ማረጋገጫ ቅጽ","fields":[{"name":"fullName","type":"text","labelAm":"ሙሉ ስም (ከነ አያት)","labelEn":"Full Name","required":true,"validation":{"minLength":3,"maxLength":100}},{"name":"baptismalName","type":"text","labelAm":"የክርስትና ስም","labelEn":"Baptismal Name","required":true,"validation":{"minLength":2}},{"name":"memberNo","type":"text","labelAm":"የአባልነት መለያ ቁጥር","labelEn":"Member ID Number","required":true,"validation":{"pattern":"^AS-\\\\d{4}-\\\\d{4}$"},"placeholderAm":"ምሳሌ፦ AS-2026-0001"},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone Number","required":true,"validation":{"minLength":9,"maxLength":20}},{"name":"email","type":"text","labelAm":"ኢሜይል አድራሻ","labelEn":"Email Address","required":false,"validation":{"pattern":"^[\\\\w-\\\\.]+@([\\\\w-]+\\\\.)+[\\\\w-]{2,4}$"}},{"name":"currentDepartment","type":"dropdown","labelAm":"ያሉበት የአገልግሎት ክፍል","labelEn":"Current Service Department","required":true,"options":[{"value":"ትምህርት","labelAm":"የትምህርት ክፍል","labelEn":"Education Department"},{"value":"መዝሙር","labelAm":"የመዝሙር ክፍል","labelEn":"Choir & Hymn Department"},{"value":"ልማት","labelAm":"የልማትና ገቢ ማሰባሰቢያ ክፍል","labelEn":"Development & Finance"},{"value":"ኪነጥበብ","labelAm":"የኪነ ጥበብና ድራማ ክፍል","labelEn":"Arts & Media"},{"value":"ሕፃናት","labelAm":"የሕፃናትና ታዳጊዎች ክፍል","labelEn":"Children & Youth"}]},{"name":"confessionFather","type":"text","labelAm":"የንስሐ አባት ስምና ቤተክርስቲያን","labelEn":"Confession Father & Parish","required":true,"validation":{"minLength":3}},{"name":"renewalYear","type":"number","labelAm":"የእድሳት ዓመተ ምሕረት (ዓ.ም)","labelEn":"Renewal Year (E.C)","required":true,"validation":{"min":2015,"max":2030}},{"name":"renewDate","type":"date","labelAm":"የማደሻ ቀን","labelEn":"Renewal Date","required":true},{"name":"serviceCommitment","type":"radio","labelAm":"የአገልግሎት ቁርጠኝነት ደረጃ","labelEn":"Service Commitment Level","required":true,"options":[{"value":"ሙሉ ጊዜ","labelAm":"ሙሉ ጊዜ (በየሳምንቱ ቅዳሜና እሑድ)","labelEn":"Full Time"},{"value":"በከፊል","labelAm":"በከፊል (በተመረጡ ቀናት)","labelEn":"Part Time"},{"value":"ልዩ ዝግጅት","labelAm":"በልዩ በዓላትና ዝግጅቶች ብቻ","labelEn":"Special Events Only"}]},{"name":"receiptFile","type":"file","labelAm":"የዓመታዊ መዋጮ ደረሰኝ ወይም ማረጋገጫ (ካለ)","labelEn":"Payment / Contribution Receipt (Optional)","required":false,"validation":{"allowedMimeTypes":["image/jpeg","image/png","image/webp","application/pdf"],"maxSizeBytes":5242880}},{"name":"agreement","type":"checkbox","labelAm":"የሰንበት ትምህርት ቤቱን መተዳደሪያ ደንብና መንፈሳዊ ሥነ-ምግባር አከብራለሁ","labelEn":"I commit to following the Sunday School constitution and ethics","required":true}],"settings":{"allowOneResponsePerMember":true}}', 'open', NULL, 1, 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', '2026-10-17T18:40:56.554Z', '2026-10-17T18:40:57.956Z');

DROP TABLE IF EXISTS `form_responses`;
CREATE TABLE `form_responses` (
  `id` char(36) NOT NULL,
  `formId` char(36) NOT NULL,
  `memberId` char(36) DEFAULT NULL,
  `answers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`answers`)),
  `status` enum('submitted','approved','rejected') NOT NULL DEFAULT 'submitted',
  `reviewNote` text DEFAULT NULL,
  `reviewedBy` char(36) DEFAULT NULL,
  `submittedAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `form_responses_formId_idx` (`formId`),
  KEY `form_responses_memberId_idx` (`memberId`),
  KEY `form_responses_status_idx` (`status`),
  CONSTRAINT `form_responses_formId_fkey` FOREIGN KEY (`formId`) REFERENCES `forms` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `form_responses_memberId_fkey` FOREIGN KEY (`memberId`) REFERENCES `members` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

