DROP TABLE IF EXISTS `lessons`;
CREATE TABLE `lessons` (
  `id` char(36) NOT NULL,
  `courseId` char(36) NOT NULL,
  `title` varchar(200) NOT NULL,
  `content` longtext DEFAULT NULL,
  `mediaType` enum('text','pdf','audio','video','link') NOT NULL DEFAULT 'text',
  `fileUrl` varchar(500) DEFAULT NULL,
  `orderNo` int(11) NOT NULL DEFAULT 1,
  `published` tinyint(1) NOT NULL DEFAULT 0,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `lessons_courseId_idx` (`courseId`),
  KEY `lessons_orderNo_idx` (`orderNo`),
  CONSTRAINT `lessons_courseId_fkey` FOREIGN KEY (`courseId`) REFERENCES `courses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `lessons` (`id`, `courseId`, `title`, `content`, `mediaType`, `fileUrl`, `orderNo`, `published`, `createdAt`, `updatedAt`) VALUES ('0b8f8423-6125-473f-8c5c-ac96227c1919', '00ddec9c-c0fd-444e-bc2f-70266bb175b1', 'ክፍል ፬፡ ማጠቃለያና የጥያቄዎች መልስ', 'ይህ የትምህርቱ 4ኛ ሳምንት ይዘት ነው። ጥልቅ መንፈሳዊ ትንታኔና የቅዱሳን አበው ትምህርት በዝርዝር ተካቷል።', 'text', NULL, 4, 1, '2026-10-17T17:56:56.321Z', '2026-10-17T17:56:56.321Z');
