DROP TABLE IF EXISTS `members`;
CREATE TABLE `members` (
  `id` char(36) NOT NULL,
  `memberNo` varchar(50) NOT NULL,
  `userId` char(36) DEFAULT NULL,
  `firstName` varchar(100) NOT NULL,
  `fatherName` varchar(100) NOT NULL,
  `grandfatherName` varchar(100) DEFAULT NULL,
  `baptismalName` varchar(100) DEFAULT NULL,
  `sex` enum('male','female') NOT NULL,
  `dateOfBirth` datetime(3) DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `email` varchar(191) DEFAULT NULL,
  `region` varchar(100) DEFAULT NULL,
  `zone` varchar(100) DEFAULT NULL,
  `woreda` varchar(100) DEFAULT NULL,
  `kebele` varchar(100) DEFAULT NULL,
  `addressDetail` text DEFAULT NULL,
  `parish` varchar(191) DEFAULT NULL,
  `confessionFather` varchar(191) DEFAULT NULL,
  `educationLevel` varchar(100) DEFAULT NULL,
  `occupation` varchar(100) DEFAULT NULL,
  `emergencyName` varchar(100) DEFAULT NULL,
  `emergencyPhone` varchar(50) DEFAULT NULL,
  `departmentId` int(11) DEFAULT NULL,
  `photoUrl` varchar(500) DEFAULT NULL,
  `status` enum('pending','active','inactive','graduated','transferred') NOT NULL DEFAULT 'active',
  `joinedAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `notes` text DEFAULT NULL,
  `createdBy` char(36) DEFAULT NULL,
  `deletedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `members_memberNo_key` (`memberNo`),
  UNIQUE KEY `members_userId_key` (`userId`),
  KEY `members_departmentId_idx` (`departmentId`),
  KEY `members_status_idx` (`status`),
  KEY `members_phone_idx` (`phone`),
  KEY `members_deletedAt_idx` (`deletedAt`),
  FULLTEXT KEY `members_firstName_fatherName_grandfatherName_baptismalName_idx` (`firstName`,`fatherName`,`grandfatherName`,`baptismalName`),
  CONSTRAINT `members_departmentId_fkey` FOREIGN KEY (`departmentId`) REFERENCES `departments` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `members_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

