DROP TABLE IF EXISTS `mezmurs`;
CREATE TABLE `mezmurs` (
  `id` char(36) NOT NULL,
  `title` varchar(255) NOT NULL,
  `lyrics` longtext DEFAULT NULL,
  `categoryId` int(11) DEFAULT NULL,
  `singer` varchar(150) DEFAULT NULL,
  `audioUrl` varchar(500) DEFAULT NULL,
  `videoUrl` varchar(500) DEFAULT NULL,
  `isPublic` tinyint(1) NOT NULL DEFAULT 1,
  `createdBy` char(36) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `mezmurs_categoryId_idx` (`categoryId`),
  KEY `mezmurs_isPublic_idx` (`isPublic`),
  FULLTEXT KEY `mezmurs_title_lyrics_idx` (`title`,`lyrics`),
  CONSTRAINT `mezmurs_categoryId_fkey` FOREIGN KEY (`categoryId`) REFERENCES `mezmur_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('2b429c2b-f837-446f-aff5-06b5aa51f331', 'ጊዮርጊስ ኃያል ሰማዕት', 'ጊዮርጊስ ተጋዳይ በፈተና የጸና፤ አክሊለ ክብርን ተቀዳጀ በጽናት።', 5, 'ዘማሪ ዲ/ን ዘርዓያዕቆብ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.750Z', '2026-10-17T17:56:56.750Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('301d06eb-ac5b-4ebf-ac68-acb4f4e5b0b5', 'ሩፋኤል ፈዋሽ መልአክ', 'ሕመምን አርቆ ጤናን የሚያድል፤ ሩፋኤል ሊቀ መላእክት ይቁም ከጎናችን።', 4, 'ዘማሪ ዲ/ን አስቻለው', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.773Z', '2026-10-17T17:56:56.773Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('51fcbd9a-70bf-4068-a645-46d318c1e7e3', 'አማኑኤል አምላካችን 2348', NULL, NULL, NULL, 'https://example.com/audio/sample-mezmur.mp3', NULL, 1, 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', '2026-10-17T18:09:52.702Z', '2026-10-17T18:09:52.702Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('570dec9c-803d-42f2-aaf6-4bde1539b477', 'ጽዮን ሆይ ደስ ይበልሽ', 'ጽዮን ሆይ ደስ ይበልሽ ንጉሥሽ ይመጣል፤ ጻድቅና አዳኝ የሆነው ጌታ።', 7, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.802Z', '2026-10-17T17:56:56.802Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('598a85b6-c779-41ed-821f-dbe4b9739d91', 'ገብርኤል አብሳሪው', 'ብስራተ ሰላምን ይዞ የመጣው፤ ገብርኤል መልአከ እግዚአብሔር ነው።', 4, 'ዘማሪ ይስሐቅ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.742Z', '2026-10-17T17:56:56.742Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('611ac262-6954-4d2e-bd01-909fa29319fe', 'ቅዱስ ሚካኤል ሊቀ መላእክት', 'ቅዱስ ሚካኤል ቆሟል በፊታችን፤ ታዳጊ መልአክ ነው ለመከራችን።', 4, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.697Z', '2026-10-17T17:56:56.697Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('6d4ba5a0-2fab-4df8-b7ed-2b014150ae7e', 'ቸርነትህ ብዙ ነው', 'ቸርነትህ ብዙ ነው ምህረትህም አያልቅም፤ አቤቱ አምላካችን ስምህ የተመሰገነ ይሁን።', 1, 'ሊቀ መዘምራን ቴዎድሮስ ዮሴፍ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.675Z', '2026-10-17T17:56:56.675Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('764fd6d5-4c7a-4f9e-88e6-bf9d59317712', 'በጾም በጸሎት እንትጋ', 'በጾም በጸሎት ወደ አምላክ እንቅረብ፤ የልብ ንጽሕናን ከእርሱ እንቀበል።', 6, 'ዘማሪት ፋንቱ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.811Z', '2026-10-17T17:56:56.811Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('7d91963b-48ed-4672-8b9f-f1be8f4b3639', 'አቡነ አረጋዊ ዘደብረ ዳሞ', 'ዘንዶውን በገመድ አስይዞ የረዳህ፤ ደብረ ዳሞ ላይ በጸሎት የጸናህ።', 5, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.785Z', '2026-10-17T17:56:56.785Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('9848a547-6d41-4f9d-bdbb-67101902e3ee', 'ነፍሴ ሆይ እግዚአብሔርን ባርኪ', 'ነፍሴ ሆይ እግዚአብሔርን ባርኪ፤ ምስጋናውንም አትርሺ።', 1, 'ዘማሪ ዲ/ን ቴዎድሮስ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.793Z', '2026-10-17T17:56:56.793Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('9a88646c-2596-4f46-b4d5-542d2a271afe', 'ሰላም ለኪ ማርያም ድንግል', 'ሰላም ለኪ ማርያም ድንግል ንጽሕት፤ በጸሎትሽ ጠብቂን ከመከራ ሕይወት።', 2, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.684Z', '2026-10-17T17:56:56.684Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('a1deeb44-0b77-4576-8c85-c246bd1b0edf', 'እልል በሉ በአንድነት', 'እልል በሉ በአንድነት ለእግዚአብሔር ክብር፤ ድንቅ ሥራውን በምድር ላይ አሳይቷልና።', 7, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.820Z', '2026-10-17T17:56:56.820Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('a4483a21-e123-4ad9-8ac0-a5eadc446952', 'አቤቱ ይቅር በለን', 'አቤቱ እንደ ቸርነትህ ይቅር በለን፤ እንደ ምህረትህም ብዛት በደላችንን ደምስስ።', 6, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.709Z', '2026-10-17T17:56:56.709Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('aed06ecf-3637-4edd-81d6-daffe041070b', 'በቀራንዮ መስቀል ላይ', 'በቀራንዮ ተሰቅሎ አዳነን፤ በክቡር ደሙ ፈሳሽነት ከኃጢአት አነጻን።', 3, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.758Z', '2026-10-17T17:56:56.758Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('b29f49eb-65d2-4a1a-923e-5cf08fd8dc0e', 'አማኑኤል አምላካችን 5444', NULL, NULL, NULL, 'https://example.com/audio/sample-mezmur.mp3', NULL, 1, 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', '2026-10-17T18:40:46.011Z', '2026-10-17T18:40:46.011Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('b31e0185-462c-41b2-bd40-824a6800e5de', 'መስቀል ኃይላችን ነው', 'መስቀል ኃይላችን ነው መስቀል ቤዛችን ነው፤ በክርስቶስ መስቀል ድኅነት አግኝተናል።', 3, 'ዘማሪ ዲ/ን ቴዎድሮስ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.691Z', '2026-10-17T17:56:56.691Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('b73385f3-dfe8-4661-a09e-27db5c874055', 'እንኳን አደረሳችሁ ለብርሃነ መስቀሉ', 'መስቀል አበራ በደመና፤ ደስ ይበለን በሃይማኖት ሆነን ሁላችን በአንድነት።', 7, 'ሊቀ መዘምራን ኪነጥበብ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.715Z', '2026-10-17T17:56:56.715Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('dfc958be-bdd7-43e4-ba35-91c116d7d7c3', 'ሥላሴን አመስግኑ', 'አንድነቱን ሳንለይ ሦስትነቱን ሳንቀላቅል፤ ለአብ ለወልድ ለመንፈስ ቅዱስ ክብር ምስጋና ይሁን።', 1, 'ዘማሪ ዲ/ን ልዑለቃል', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.720Z', '2026-10-17T17:56:56.720Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('ed4862f5-95b4-483f-b279-5f55d6b52820', 'ጻድቁ አባታችን ተክለ ሃይማኖት', 'ተክለ ሃይማኖት ጸሎትህ አይለየን፤ በምልጃህ ጸንተን በበረከት እንኑር።', 5, 'ዘማሪት ፋንቱ ወልዴ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.703Z', '2026-10-17T17:56:56.703Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('f276da5c-50a3-46bc-9b8e-c6142ab6c034', 'እግዚአብሔር ብርሃኔና መድኃኒቴ ነው', 'እግዚአብሔር ብርሃኔና መድኃኒቴ ነው፤ የሚያስፈራኝ ማን ነው?', 3, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.734Z', '2026-10-17T17:56:56.734Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('f8a67414-8f1d-4e9a-9fc2-753bf3455bbb', 'ማርያም ድንግል እናቴ', 'ማርያም ድንግል እናቴ አንቺ ነሽ ዋስትናዬ፤ ባንቺ አማላጅነት ይብራ ዘመኔ።', 2, 'ዘማሪት ምርትነሽ ጥላሁን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.727Z', '2026-10-17T17:56:56.727Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('fb997310-7a93-450e-9c72-f9a6ead8d25e', 'ድንግል ሆይ ስምሽን ስጠራ', 'ስምሽን ስጠራ ልቤ ይረካል፤ በአማላጅነትሽ ጥላ ከለላ ያገኛል።', 2, 'ዘማሪት ሲስተር ልኬለሽ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.765Z', '2026-10-17T17:56:56.765Z');

