  `title` varchar(255) NOT NULL,
  `body` text DEFAULT NULL,
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`data`)),
  `sentAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `readAt` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `notifications_userId_idx` (`userId`),
  KEY `notifications_sentAt_idx` (`sentAt`),
  KEY `notifications_readAt_idx` (`readAt`),
  CONSTRAINT `notifications_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `notifications` (`id`, `userId`, `title`, `body`, `data`, `sentAt`, `readAt`) VALUES ('1dbacf18-2d5b-4d50-a58f-98def7a27c41', '020b0784-2982-4d83-8c4b-07be91952ce3', '🚨 አስቸኳይ፡ የዕለቱ ስንክሳር ጥቅምት ፯ - 8490', '<p>ይህ የዕለቱ ስንክሳር ንባብና የቅዱሳን አበው ገድል ነው።</p>', '{"postId":"6807c844-591a-47ae-b722-72ad17a89976","postType":"sinksar","isUrgent":true}', '2026-10-17T18:09:49.085Z', NULL);
INSERT INTO `notifications` (`id`, `userId`, `title`, `body`, `data`, `sentAt`, `readAt`) VALUES ('3a711950-1957-4f99-9057-97f472c613a7', 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', '🚨 አስቸኳይ፡ የዕለቱ ስንክሳር ጥቅምት ፯ - 8643', '<p>ይህ የዕለቱ ስንክሳር ንባብና የቅዱሳን አበው ገድል ነው።</p>', '{"postId":"985bbe20-939f-41cc-a591-0e53f54b3f0b","postType":"sinksar","isUrgent":true}', '2026-10-17T18:40:40.322Z', NULL);
INSERT INTO `notifications` (`id`, `userId`, `title`, `body`, `data`, `sentAt`, `readAt`) VALUES ('3d1ad6f7-4b62-4f53-9e65-808d98a0d589', 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', '🚨 አስቸኳይ፡ አስቸኳይ ማስታወቂያ፡ ልዩ የጸሎትና የምልጃ መርሐ ግብር', 'ለሁሉም የሰንበት ትምህርት ቤት አባላት፡ በመጪው ዓርብ ከምሽቱ 11:30 ጀምሮ ልዩ የጋራ ጸሎት ይደረጋል፤ ሳያቋርጡ ይገኙ።', '{"postId":"09d4da82-6bf1-4d8c-a1ef-5b81a1ee665c","postType":"urgent","isUrgent":true}', '2026-10-17T17:58:00.039Z', NULL);
INSERT INTO `notifications` (`id`, `userId`, `title`, `body`, `data`, `sentAt`, `readAt`) VALUES ('58c2f5d2-7f26-483b-8951-e6e20e14f47b', 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', '🚨 አስቸኳይ፡ የዕለቱ ስንክሳር ጥቅምት ፯ - 8490', '<p>ይህ የዕለቱ ስንክሳር ንባብና የቅዱሳን አበው ገድል ነው።</p>', '{"postId":"6807c844-591a-47ae-b722-72ad17a89976","postType":"sinksar","isUrgent":true}', '2026-10-17T18:09:49.085Z', NULL);
INSERT INTO `notifications` (`id`, `userId`, `title`, `body`, `data`, `sentAt`, `readAt`) VALUES ('6fcd3a7e-55fa-4f26-953e-dd83d54357a8', '020b0784-2982-4d83-8c4b-07be91952ce3', '🚨 አስቸኳይ፡ አስቸኳይ ማስታወቂያ፡ ልዩ የጸሎትና የምልጃ መርሐ ግብር', 'ለሁሉም የሰንበት ትምህርት ቤት አባላት፡ በመጪው ዓርብ ከምሽቱ 11:30 ጀምሮ ልዩ የጋራ ጸሎት ይደረጋል፤ ሳያቋርጡ ይገኙ።', '{"postId":"09d4da82-6bf1-4d8c-a1ef-5b81a1ee665c","postType":"urgent","isUrgent":true}', '2026-10-17T17:58:00.039Z', NULL);
INSERT INTO `notifications` (`id`, `userId`, `title`, `body`, `data`, `sentAt`, `readAt`) VALUES ('71cf5f05-c236-41ce-8151-48c3c5220149', '020b0784-2982-4d83-8c4b-07be91952ce3', '🚨 አስቸኳይ፡ የዕለቱ ስንክሳር ጥቅምት ፯ - 8643', '<p>ይህ የዕለቱ ስንክሳር ንባብና የቅዱሳን አበው ገድል ነው።</p>', '{"postId":"985bbe20-939f-41cc-a591-0e53f54b3f0b","postType":"sinksar","isUrgent":true}', '2026-10-17T18:40:40.322Z', NULL);

DROP TABLE IF EXISTS `posts`;
CREATE TABLE `posts` (
  `id` char(36) NOT NULL,
  `type` enum('sinksar','bible_reading','saint_of_day','urgent','event','news','teaching') NOT NULL DEFAULT 'news',
  `title` varchar(255) NOT NULL,
  `body` longtext NOT NULL,
  `imageUrl` varchar(500) DEFAULT NULL,
  `isUrgent` tinyint(1) NOT NULL DEFAULT 0,
  `publishAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `expiresAt` datetime(3) DEFAULT NULL,
  `authorId` char(36) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `posts_type_idx` (`type`),
  KEY `posts_isUrgent_idx` (`isUrgent`),
  KEY `posts_publishAt_idx` (`publishAt`),
  KEY `posts_authorId_idx` (`authorId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('016f2716-5f88-4de4-b0e1-e6e5967f7f20', 'saint_of_day', 'የዕለቱ ቅዱስ፡ አባ ጳውሊ ታላቁ ገዳማዊ', 'የገዳማዊ ሕይወት ቀዳሚ የሆኑት አባ ጳውሊ በበረሃ የኖሩበት ገድልና ድንቅ መንፈሳዊ ተጋድሎ።', NULL, 0, '2026-10-17T17:56:56.859Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.859Z', '2026-10-17T17:56:56.859Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('09d4da82-6bf1-4d8c-a1ef-5b81a1ee665c', 'urgent', 'አስቸኳይ ማስታወቂያ፡ ልዩ የጸሎትና የምልጃ መርሐ ግብር', 'ለሁሉም የሰንበት ትምህርት ቤት አባላት፡ በመጪው ዓርብ ከምሽቱ 11:30 ጀምሮ ልዩ የጋራ ጸሎት ይደረጋል፤ ሳያቋርጡ ይገኙ።', NULL, 1, '2026-10-17T17:56:56.873Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.873Z', '2026-10-17T17:56:56.873Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('3ea6a392-36e5-4719-b98a-6b28a93ba8e4', 'teaching', 'ስለ አሥራትና በኩራት ትምህርት', '«በቤቴ ውስጥ መብል እንዲሆን አሥራቱን ሁሉ ወደ ጎተራ አግቡ» - ሚልክያስ ፫:፲። የክርስትና የልግስና መርሆዎች።', NULL, 0, '2026-10-17T17:56:56.892Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.892Z', '2026-10-17T17:56:56.892Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('6807c844-591a-47ae-b722-72ad17a89976', 'sinksar', 'የዕለቱ ስንክሳር ጥቅምት ፯ - 8490', '<p>ይህ የዕለቱ ስንክሳር ንባብና የቅዱሳን አበው ገድል ነው።</p>', NULL, 1, '2026-10-17T18:09:00.000Z', NULL, 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', '2026-10-17T18:09:49.057Z', '2026-10-17T18:09:49.057Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('6b7ca6db-c408-4233-9777-fa1bcd3fceab', 'news', 'የመዘምራን ክፍል አዲስ አልበም ዝግጅት', 'የመዝሙር ክፍሉ አዲስ መንፈሳዊ ያሬዳዊ የዝማሬ አልበም ለማዘጋጀት ልምምድ ጀምሯል።', NULL, 0, '2026-10-17T17:56:56.904Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.904Z', '2026-10-17T17:56:56.904Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('9303aa06-e86a-4641-934a-165900f1e887', 'event', 'ዓመታዊ የሰንበት ትምህርት ቤት የምስረታ በዓል', 'አዕማደ ሰላም ሰንበት ትምህርት ቤት የተመሰረተበትን 26ኛ ዓመት በልዩ መንፈሳዊ ድግስ እናከብራለን።', NULL, 0, '2026-10-17T17:56:56.880Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.880Z', '2026-10-17T17:56:56.880Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('985bbe20-939f-41cc-a591-0e53f54b3f0b', 'sinksar', 'የዕለቱ ስንክሳር ጥቅምት ፯ - 8643', '<p>ይህ የዕለቱ ስንክሳር ንባብና የቅዱሳን አበው ገድል ነው።</p>', NULL, 1, '2026-10-17T18:40:00.000Z', NULL, 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', '2026-10-17T18:40:39.966Z', '2026-10-17T18:40:39.966Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('b762ae63-f8c0-40d5-9640-bb8e0f6d3f6e', 'sinksar', 'የዕለቱ ስንክሳር፡ ጥቅምት ፪', 'በዚህች ዕለት የከበሩ ጻድቃንና ሰማዕታት መታሰቢያቸው ሆነ፤ ጸሎታቸውና ምልጃቸው ከሁላችን ጋር ይሁን።', NULL, 0, '2026-10-17T17:56:56.835Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.835Z', '2026-10-17T17:56:56.835Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('ca1c94ea-3df4-4252-856e-99b02f45419e', 'bible_reading', 'የዕለቱ የቅዱስ ወንጌል ንባብ', '«እኔ የመንገድ እውነትና ሕይወት ነኝ፤ በእኔ በቀር ወደ አብ የሚመጣ ማንም የለም» - ዮሐንስ ፲፬:፮', NULL, 0, '2026-10-17T17:56:56.848Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.848Z', '2026-10-17T17:56:56.848Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('d20b5598-387b-4066-be81-9514b46950a5', 'teaching', 'የሰንበት ትምህርት ቤት አስፈላጊነት በዘመናችን', 'ሰንበት ትምህርት ቤት የቤተ ክርስቲያን የጀርባ አጥንት ናት። ሕፃናትና ወጣቶች በእውነተኛው ሃይማኖትና ምግባር የሚታነጹበት ማዕከል ናት።', NULL, 0, '2026-10-17T17:56:56.866Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.866Z', '2026-10-17T17:56:56.866Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('fe551855-4ec4-4569-bd32-9744e4dfb366', 'sinksar', 'የጥቅምት ወር የበዓላት ማውጫ', 'በዚህ ወር የሚከበሩ ዓበይትና ንዑሳን የቅዱሳን በዓላት ዝርዝርና መርሐ ግብራቸው።', NULL, 0, '2026-10-17T17:56:56.898Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.898Z', '2026-10-17T17:56:56.898Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('fe6a11c0-fd9e-4247-a702-d0316ebc7724', 'news', 'የአዲስ ተማሪዎች ምዝገባ ተጀመረ', 'ለ2019 ዓ.ም የትምህርት ዘመን ከደረጃ ፩ እስከ ፬ የአዲስ ተማሪዎች ምዝገባ በይፋ ተከፍቷል።', NULL, 0, '2026-10-17T17:56:56.886Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.886Z', '2026-10-17T17:56:56.886Z');

DROP TABLE IF EXISTS `refresh_tokens`;
CREATE TABLE `refresh_tokens` (
  `id` char(36) NOT NULL,
  `userId` char(36) NOT NULL,
  `tokenHash` varchar(255) NOT NULL,
  `expiresAt` datetime(3) NOT NULL,
  `revoked` tinyint(1) NOT NULL DEFAULT 0,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `refresh_tokens_userId_idx` (`userId`),
  KEY `refresh_tokens_tokenHash_idx` (`tokenHash`),
  CONSTRAINT `refresh_tokens_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `refresh_tokens` (`id`, `userId`, `tokenHash`, `expiresAt`, `revoked`, `createdAt`) VALUES ('0021ff0f-cb8e-42b1-b913-7c97439eda1b', 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', '40f58195d8890f9d59c371d24c67d5501b58e61f977fec5e41c64fb159b64830', '2026-10-24T18:40:44.543Z', 0, '2026-10-17T18:40:44.545Z');
